// src/App.js
import React, { useEffect, useState } from "react";
import {
  BrowserRouter as Router,
  Routes,
  Route,
  Navigate,
} from "react-router-dom";

import AdminDashboard from "./components/Admin/AdminDashboard";
import HomePage from "./components/User/HomePage";
import CheckoutPage from "./components/User/CheckoutPage";
import ThankYouPage from "./components/User/ThankYouPage";

import { INITIAL_MENU, INITIAL_ORDERS, INITIAL_CHEFS } from "./mockData";
import "./App.css";

/* -------------------- localStorage helpers -------------------- */
const load = (key, fallback) => {
  try {
    const v = localStorage.getItem(key);
    return v ? JSON.parse(v) : fallback;
  } catch {
    return fallback;
  }
};
const save = (key, val) => {
  try {
    localStorage.setItem(key, JSON.stringify(val));
  } catch {}
};

/* -------------------- default 30 tables -------------------- */
const makeTables = () =>
  Array.from({ length: 30 }, (_, i) => ({
    id: `t${i + 1}`,
    number: i + 1,
    name: null,
    size: [2, 4, 6, 8][i % 4],
    status: "Available",
  }));

export default function App() {
  /* -------------------- app state -------------------- */
  const [menuItems, setMenuItems] = useState(() =>
    load("menuItems", INITIAL_MENU)
  );
  const [tables, setTables] = useState(() => load("tables", makeTables()));
  const [orders, setOrders] = useState(() => load("orders", INITIAL_ORDERS));
  const [chefs, setChefs] = useState(() => load("chefs", INITIAL_CHEFS));
  const [cart, setCart] = useState(() => load("cart", []));
  const [totalClients, setTotalClients] = useState(() =>
    load("totalClients", 0)
  );

  // user details captured on first visit
  const [isModalOpen, setIsModalOpen] = useState(true);
  const [userDetails, setUserDetails] = useState(null);

  /* -------------------- persist -------------------- */
  useEffect(() => save("menuItems", menuItems), [menuItems]);
  useEffect(() => save("tables", tables), [tables]);
  useEffect(() => save("orders", orders), [orders]);
  useEffect(() => save("chefs", chefs), [chefs]);
  useEffect(() => save("cart", cart), [cart]);
  useEffect(() => save("totalClients", totalClients), [totalClients]);

  /* -------------------- admin: products & tables -------------------- */
  const addProduct = (p) => {
    setMenuItems((m) => [
      ...m,
      {
        id: `p${Date.now()}`,
        ...p,
        description: p.description || "No description",
        averagePreparationTime: p.averagePreparationTime || 10,
        stock: p.stock || "In Stock",
      },
    ]);
  };

  const addTable = (data) => {
    setTables((prev) => [
      ...prev,
      {
        id: `t${prev.length + 1}`,
        number: prev.length + 1,
        name: data.name || null,
        size: parseInt(data.size, 10) || 4,
        status: "Available",
      },
    ]);
  };

  const deleteTable = (tableId) => {
    setTables((prev) =>
      prev
        .filter((t) => t.id !== tableId)
        .map((t, idx) => ({ ...t, number: idx + 1 }))
    );
  };

  /* -------------------- chefs helpers -------------------- */
  const chooseLeastBusyChefId = () => {
    if (!chefs.length) return null;
    const chosen = chefs.reduce(
      (best, c) => ((c.orders ?? 0) < (best.orders ?? 0) ? c : best),
      chefs[0]
    );
    return chosen.id;
  };

  const bumpChefLoad = (chefId, delta) => {
    if (!chefId) return;
    setChefs((prev) =>
      prev.map((c) =>
        c.id === chefId
          ? { ...c, orders: Math.max(0, (c.orders ?? 0) + delta) }
          : c
      )
    );
  };

  /* -------------------- order status updates -------------------- */
  const updateOrderStatus = (orderId, newStatus) => {
    const target = orders.find((o) => o.id === orderId);

    setOrders((prev) =>
      prev.map((o) =>
        o.id === orderId
          ? {
              ...o,
              status: newStatus,
              doneAt: newStatus === "done" && !o.doneAt ? Date.now() : o.doneAt,
            }
          : o
      )
    );

    if (!target) return;

    // free table when a dine-in order is completed
    if (
      newStatus === "done" &&
      target.type === "Dine In" &&
      typeof target.table === "string" &&
      target.table.startsWith("Table-")
    ) {
      const num = parseInt(target.table.replace("Table-", ""), 10);
      setTables((prev) =>
        prev.map((t) => (t.number === num ? { ...t, status: "Available" } : t))
      );
    }

    // decrement that chef's load
    if (newStatus === "done") bumpChefLoad(target.chefId, -1);
  };

  /* -------------------- cart helpers -------------------- */
  const addToCart = (item) => {
    setCart((prev) => {
      const ex = prev.find((i) => i.id === item.id);
      if (ex) {
        const q = item.quantity ?? ex.quantity + 1;
        if (q <= 0) return prev.filter((i) => i.id !== item.id);
        return prev.map((i) => (i.id === item.id ? { ...i, quantity: q } : i));
      }
      return [...prev, { ...item, quantity: 1 }];
    });
  };

  const updateCart = (id, qty) =>
    setCart((prev) =>
      qty <= 0
        ? prev.filter((i) => i.id !== id)
        : prev.map((i) => (i.id === id ? { ...i, quantity: qty } : i))
    );

  /* -------------------- place order -------------------- */
  const placeOrder = (details) => {
    const placedAt = Date.now();
    const id = (orders[0]?.id || 0) + 1; // simple increasing id (top insert)
    const isDine = details.type === "Dine In";
    const isTake = details.type === "Take Away";

    // choose and bump chef
    const chefId = chooseLeastBusyChefId();
    bumpChefLoad(chefId, +1);

    // label & reserve table for dine-in
    let tableLabel = "Takeaway";
    if (isDine) {
      if (details.tableNum && details.tableNum !== "N/A") {
        const n = parseInt(details.tableNum, 10);
        tableLabel = `Table-${n}`;
        setTables((prev) =>
          prev.map((t) => (t.number === n ? { ...t, status: "Reserved" } : t))
        );
      } else {
        tableLabel = "Dine In";
      }
    }

    const durationMinutes = 15; // default
    const itemCount = cart.reduce((a, i) => a + (i.quantity || 0), 0);

    // clients counting
    const dineGuests =
      parseInt(
        details.noOfPeople ||
          details.guests ||
          details.people ||
          details.members ||
          0,
        10
      ) || 0;
    const takeGuests =
      parseInt(
        details.takeawayMem ||
          details.takeawayMembers ||
          details.members ||
          details.people ||
          0,
        10
      ) || 0;

    if (isDine || isTake) {
      const inc = (isDine ? dineGuests : 0) + (isTake ? takeGuests : 0);
      if (inc > 0) setTotalClients((prev) => prev + inc);
    }

    const newOrder = {
      id,
      items: cart,
      itemCount,
      status: "processing",
      type: details.type, // "Dine In" | "Take Away"
      table: tableLabel, // "Table-3" | "Dine In" | "Takeaway"
      time: new Date(placedAt).toLocaleTimeString("en-US", {
        hour: "2-digit",
        minute: "2-digit",
      }),
      placedAt,
      startedAt: placedAt,
      durationMinutes,

      // customer identity
      name: details.name || "",
      contact: details.contact || "", // phone
      address: details.address || "",

      // counts
      guests: dineGuests, // dine-in
      takeawayGuests: takeGuests, // take-away

      // chef
      chefId,
    };

    setOrders((prev) => [newOrder, ...prev]); // add on top
    setCart([]); // clear cart
  };

  /* -------------------- first-visit modal -------------------- */
  const handleDetailsSubmit = (d) => {
    setUserDetails(d);
    setIsModalOpen(false);
  };

  /* -------------------- Router (auto basename) -------------------- */
  const basename =
    process.env.NODE_ENV === "production"
      ? "/RESTAURANT-MANAGEMENT"
      : "/";

  return (
    <Router basename={basename}>
      <Routes>
        <Route
          path="/"
          element={
            <HomePage
              menu={menuItems}
              cart={cart}
              addToCart={addToCart}
              isModalOpen={isModalOpen}
              onDetailsSubmit={handleDetailsSubmit}
            />
          }
        />
        <Route
          path="/checkout"
          element={
            <CheckoutPage
              cart={cart}
              updateCart={updateCart}
              placeOrder={placeOrder}
              tables={tables}
              userDetails={userDetails}
            />
          }
        />
        <Route path="/thankyou" element={<ThankYouPage />} />
        <Route
          path="/admin"
          element={
            <AdminDashboard
              orders={orders}
              tables={tables}
              menuItems={menuItems}
              chefs={chefs}
              totalClients={totalClients}
              updateOrderStatus={updateOrderStatus}
              deleteTable={deleteTable}
              addTable={addTable}
              addProduct={addProduct}
            />
          }
        />
        <Route path="*" element={<Navigate to="/" />} />
      </Routes>
    </Router>
  );
}
